using System.Text.Json;
using Hexalith.Builds.Tooling.Workspace;
using Hexalith.Builds.Tooling.Runtime;
using CancellationTokenSource cancellation = new(TimeSpan.FromMinutes(3));
var probe = await CompositionProcess.RunAsync(CompositionProcess.CreateStartInfo("dotnet", ["--hexalith-controlled-interception-probe"], AppContext.BaseDirectory, null), TimeSpan.FromSeconds(10), cancellation.Token);
if (probe.ExitCode != 0 || probe.Output.Trim() != "intercepted|certificate=false|serial=1") throw new InvalidOperationException("SDK interception prerequisite failed: " + probe.Output + probe.ErrorOutput);
Console.WriteLine("Non-SDK interception prerequisite passed.");
if (args[0] == "probe-only") return;
SourceMapping mapping = await WorkspaceRootResolver.ResolveAsync(args[0], WorkspaceMode.Source, cancellation.Token);
await SourceMappingMaterializer.WriteAsync(mapping, args[1], cancellation.Token);
await File.WriteAllTextAsync(Path.Combine(args[1], "environment.json"), JsonSerializer.Serialize(SourceMappingMaterializer.Environment(mapping,args[1]), new JsonSerializerOptions { WriteIndented=true }));
Console.WriteLine(JsonSerializer.Serialize(mapping,new JsonSerializerOptions{WriteIndented=true}));
